mapper.select:
select ri.id, ri.seat_code, ri.price, ai.id store_id, ai.name, ai.introduction, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name, ai.address_detail, ai.latitude, ai.longitude, ai.phone, ai.is_release from seat ri left join study_store ai on ri.store_id = ai.id and ai.is_deleted = 0
ri.is_deleted = 0 and ri.is_release = 1 and ri.id not in (select seat_id from booking_order where is_deleted = 0 and status in (2, 5))
and ai.province_id = #{queryVo.provinceId}
and ai.city_id = #{queryVo.cityId}
and ai.district_id = #{queryVo.districtId}
and (ri.price >= #{queryVo.minPrice} and ri.price <= #{queryVo.maxPrice})
and ri.id in (select seat_id from seat_payment_type where is_deleted = 0 and payment_type_id=#{queryVo.paymentTypeId})
order by ri.price ${queryVo.orderType}
